-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id INTEGER, name TEXT);
-- INSERT INTO customers VALUES(1,'kim'),(2,'lee'),(3,'park');
-- CREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER, status TEXT);
-- INSERT INTO orders VALUES(10,1,3000,'paid'),(11,1,2000,'refund'),(12,2,4000,'paid'),(13,3,5000,'refund');
SELECT c.name, COALESCE(SUM(o.amount), 0) AS paid_total
FROM customers AS c
LEFT JOIN orders AS o ON o.customer_id = c.id
WHERE o.status = 'paid'
GROUP BY c.id
ORDER BY c.id;

